import { Injectable, computed, signal } from '@angular/core';
import { createClient } from '@supabase/supabase-js';
import { environment } from '../../environments/environment';
import { Survey, byEndDate, isPast } from '../models/survey';

/** How many cards the "Ending soon surveys" row shows. */
const ENDING_SOON_COUNT = 3;
/** localStorage key for the ids of surveys this browser already voted in. */
const VOTED_KEY = 'pollapp-voted';

/** A row of the `surveys` table in Supabase (see `supabase/schema.sql`). */
interface SurveyRow {
  /** Primary key, generated by the database. */
  id: number;
  /** Survey name. */
  title: string;
  /** One of `CATEGORIES`. */
  category: string;
  /** Optional describing text, `null` if empty. */
  description: string | null;
  /** 'YYYY-MM-DD' or `null` for surveys without an end date. */
  end_date: string | null;
  /** Questions as JSON; answers are plain texts, votes live in the `votes` table. */
  questions: { text: string; allowMultiple: boolean; answers: string[] }[];
}

/** A row of the `vote_counts` view: number of votes per answer. */
interface VoteCountRow {
  /** Survey the votes belong to. */
  survey_id: number;
  /** Index of the question within the survey. */
  question_index: number;
  /** Index of the answer within the question. */
  answer_index: number;
  /** Number of votes for this answer. */
  votes: number;
}

/**
 * Reads the ids of surveys this browser already voted in.
 *
 * @returns The ids, or an empty list if storage is empty, blocked or corrupt.
 */
function readVotedIds(): number[] {
  try {
    return JSON.parse(localStorage.getItem(VOTED_KEY) ?? '[]');
  } catch {
    return [];
  }
}

/**
 * Looks up the vote count of one answer.
 *
 * @param counts - All rows of the `vote_counts` view.
 * @param surveyId - Survey the answer belongs to.
 * @param q - Index of the question.
 * @param a - Index of the answer within the question.
 * @returns Number of votes, 0 if nobody chose it yet.
 */
function voteCount(counts: VoteCountRow[], surveyId: number, q: number, a: number): number {
  const row = counts.find(
    (c) => c.survey_id === surveyId && c.question_index === q && c.answer_index === a,
  );
  return row?.votes ?? 0;
}

/**
 * Converts a database row plus vote counts into a {@link Survey} for the UI.
 *
 * @param row - Row of the `surveys` table.
 * @param counts - All rows of the `vote_counts` view.
 * @returns The survey with votes filled in.
 */
function toSurvey(row: SurveyRow, counts: VoteCountRow[]): Survey {
  const votes = (q: number, a: number) => voteCount(counts, row.id, q, a);
  return {
    id: row.id,
    title: row.title,
    category: row.category,
    description: row.description ?? undefined,
    endDate: row.end_date ?? undefined,
    questions: row.questions.map((question, q) => ({
      text: question.text,
      allowMultiple: question.allowMultiple,
      answers: question.answers.map((text, a) => ({ text, votes: votes(q, a) })),
    })),
  };
}

/**
 * Converts a new survey from the UI into a row for the `surveys` table.
 * Vote counts are dropped because votes live in their own table.
 *
 * @param survey - The survey from the create dialog.
 * @returns The row to insert.
 */
function toRow(survey: Omit<Survey, 'id'>): Omit<SurveyRow, 'id'> {
  return {
    title: survey.title,
    category: survey.category,
    description: survey.description ?? null,
    end_date: survey.endDate ?? null,
    questions: survey.questions.map((question) => ({
      text: question.text,
      allowMultiple: question.allowMultiple,
      answers: question.answers.map((answer) => answer.text),
    })),
  };
}

/**
 * Single source of truth for all surveys.
 * Loads them from Supabase, keeps them live via Realtime and saves new surveys and votes.
 */
@Injectable({
  providedIn: 'root',
})
export class SurveyService {
  /** Supabase client, authenticated with the public (publishable) key. */
  private supabase = createClient(environment.supabaseUrl, environment.supabaseKey);

  /** All surveys including their current vote counts. */
  surveys = signal<Survey[]>([]);
  /** `true` once the first load from Supabase succeeded. */
  isLoaded = signal(false);

  /** All surveys sorted by end date, earliest first. */
  sortedSurveys = computed(() => [...this.surveys()].sort(byEndDate));

  /** The open surveys that end next, shown above the list (User Story 1). */
  endingSoon = computed(() =>
    this.sortedSurveys()
      .filter((survey) => survey.endDate && !isPast(survey))
      .slice(0, ENDING_SOON_COUNT),
  );

  /** Surveys this browser already voted in, so nobody votes twice. */
  private votedIds = signal<number[]>(readVotedIds());

  /** Loads all surveys and subscribes to new surveys and votes (live updates). */
  constructor() {
    this.load();
    // shortcut: reloads everything on each new survey/vote, fine for a few hundred surveys; switch to patching single rows if it gets slow.
    this.supabase
      .channel('pollapp')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'surveys' }, () =>
        this.load(),
      )
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'votes' }, () =>
        this.load(),
      )
      .subscribe();
  }

  /**
   * Fetches all surveys and vote counts from Supabase into {@link surveys}.
   * On an error the current data stays and the error is logged.
   */
  async load(): Promise<void> {
    const [surveys, counts] = await Promise.all([
      this.supabase.from('surveys').select('id, title, category, description, end_date, questions'),
      this.supabase.from('vote_counts').select('*'),
    ]);
    if (surveys.error || counts.error) {
      console.error('Could not load surveys', surveys.error ?? counts.error);
      return;
    }
    this.surveys.set(
      (surveys.data as SurveyRow[]).map((row) => toSurvey(row, counts.data as VoteCountRow[])),
    );
    this.isLoaded.set(true);
  }

  /**
   * Tells whether this browser already voted in a survey.
   *
   * @param id - Id of the survey.
   * @returns `true` if the survey was completed here before.
   */
  hasVoted(id: number): boolean {
    return this.votedIds().includes(id);
  }

  /**
   * Finds a loaded survey.
   *
   * @param id - Id of the survey.
   * @returns The survey, or `undefined` if it doesn't exist (yet).
   */
  getById(id: number): Survey | undefined {
    return this.surveys().find((survey) => survey.id === id);
  }

  /**
   * Saves a new survey and reloads the list.
   *
   * @param survey - The survey from the create dialog, without id.
   * @returns The id the database gave the new survey.
   * @throws The Supabase error if saving failed.
   */
  async create(survey: Omit<Survey, 'id'>): Promise<number> {
    const { data, error } = await this.supabase
      .from('surveys')
      .insert(toRow(survey))
      .select('id')
      .single();
    if (error) throw error;
    await this.load();
    return data.id;
  }

  /**
   * Saves one participant's answers and remembers that this browser voted.
   *
   * @param surveyId - Id of the survey.
   * @param selections - `selections[questionIndex]` holds the indexes of the chosen answers.
   * @throws The Supabase error if saving failed, e.g. because the survey has ended.
   */
  async vote(surveyId: number, selections: number[][]): Promise<void> {
    const rows = selections.flatMap((answers, questionIndex) =>
      (answers ?? []).map((answerIndex) => ({
        survey_id: surveyId,
        question_index: questionIndex,
        answer_index: answerIndex,
      })),
    );
    const { error } = await this.supabase.from('votes').insert(rows);
    if (error) throw error;
    this.votedIds.update((ids) => [...ids, surveyId]);
    localStorage.setItem(VOTED_KEY, JSON.stringify(this.votedIds()));
    await this.load();
  }
}
